      "Inferência é uma conclusão lógica que decorre do que foi dito, mesmo sem estar escrita literalmente — mas toda inferência correta precisa estar ancorada em alguma pista real do texto. Pressuposto é uma ideia que o texto dá como verdadeira sem precisar provar, geralmente embutida em uma palavra específica, como 'ainda', 'voltou a' ou 'continua'.",
