    "corpo": [
      "Ponto de vista é a perspectiva de onde o autor observa e avalia um fato — nem sempre está explícito, mas se revela pela escolha de palavras, pelo que o autor destaca ou omite, e pelo tom empregado.",
      "Ironia é dizer uma coisa querendo comunicar o oposto — geralmente para criticar algo sem atacar diretamente. É a figura de linguagem mais difícil de detectar em prova, porque exige perceber o contraste entre o que está escrito e o que o contexto sugere.",
      "Humor, quando aparece em textos de prova, quase sempre serve a um propósito crítico: fazer rir para fazer pensar. A banca não pergunta 'isso é engraçado?', pergunta 'qual crítica esse humor esconde?'."
    ],
    "pontosChave": [
      "Ponto de vista se revela por escolha de palavras, destaque e omissão — raramente é dito de forma explícita.",
      "Ironia comunica o oposto do que está escrito literalmente; exige perceber o contraste com o contexto.",
      "Humor em texto de prova quase sempre carrega uma crítica por trás."
    ],
    "checkRapido": {
      "pergunta": "Uma reportagem chama uma operação policial malsucedida de 'o grande feito do ano', destacando que ela custou R$ 2 milhões e resultou em zero prisões. O tom do trecho é:",
      "opcoes": [
        "Elogioso, sem ressalvas",
        "Irônico, criticando o resultado da operação",
        "Neutro e informativo"
      ],
      "correta": 1,
      "justificativa": "O contraste entre a expressão elogiosa ('grande feito') e o resultado modesto (zero prisões, alto custo) é a marca clássica de ironia — o autor diz o oposto do que quer comunicar para reforçar a crítica."
    },
    "oQueCobra": "Identificar tom irônico ou crítico a partir do contraste entre a linguagem usada e os fatos apresentados.",
    "precisaSaberAntes": "Reconhecer que ironia se detecta pelo contraste, não por uma palavra isolada que 'sinalize' ironia.",
    "explicacao": [
      {
        "titulo": "O sinal mais confiável de ironia",
        "texto": "Procure uma discrepância entre a avaliação verbal (elogio, otimismo) e os fatos concretos apresentados no mesmo trecho (números ruins, resultado fraco, consequência negativa). Esse contraste é o que sustenta a leitura irônica — nunca marque ironia baseado só em 'sensação', sempre aponte a evidência textual do contraste."
      },
      {
        "titulo": "Ponto de vista nas escolhas lexicais",
        "texto": "Um mesmo fato pode ser descrito como 'intervenção necessária' ou 'abuso de poder' — a escolha da palavra já revela de que lado o autor está. Preste atenção em adjetivos e verbos de julgamento ('infelizmente', 'felizmente', 'lamentavelmente')."
      }
    ],
    "comoIdentificar": "Questões que pedem 'o tom predominante do texto' ou 'a crítica implícita do autor' pedem leitura de ponto de vista e ironia.",
