      "Textos institucionais — ofícios, memorandos, boletins de ocorrência, editais — seguem um registro formal e impessoal, diferente da linguagem coloquial usada no dia a dia. A prova costuma testar se o candidato reconhece desvios desse padrão: uso de gírias, excesso de opinião pessoal, ou informalidade incompatível com o gênero.",
      "Impessoalidade significa que o texto fala em nome da instituição, não da pessoa que o redigiu — por isso, evita-se a primeira pessoa do singular ('eu acho') em favor de construções na terceira pessoa ou na voz passiva ('constatou-se', 'foi verificado').",
      "Clareza e concisão são exigências centrais: frases longas, com muitos incisos e informação redundante, comprometem a comunicação institucional — o objetivo é que qualquer leitor entenda a mensagem sem esforço ou ambiguidade."
